// package.json dependency contract:
// "dependencies": {
//   "citty": "^0.2.2",
//   "fast-xml-parser": "^5.2.5",
//   "typescript": "^6.0.2"
// }

/** Supported GRACE artifact grammar version for this release. */
export const GRACE4_VERSION = "4.0" as const;

/** Standard GRACE 4 root tags accepted by Artifact Grammar. */
export const GRACE4_ROOT_TAGS = [
  "GraceRequirements",
  "GraceTechnology",
  "GracePrinciples",
  "GraceDeployment",
  "GraceUXGuidelines",
  "GraceGraphIndex",
  "GraceGraphDocument",
  "GraceVerificationIndex",
  "GraceVerificationDocument",
  "GraceChangeSpec",
  "GraceChangePlan",
] as const;

/** Lifecycle statuses allowed on GraceChangeSpec and GraceChangePlan roots. */
export const CHANGE_STATUSES = ["draft", "approved", "applied", "rejected", "cancelled", "superseded"] as const;

/** Statuses valid for bundles under .grace/changes/active. */
export const ACTIVE_CHANGE_STATUSES = new Set(["draft", "approved"] as const);

/** Statuses valid for bundles under .grace/changes/archive. */
export const ARCHIVED_CHANGE_STATUSES = new Set(["applied", "rejected", "cancelled", "superseded"] as const);

/** Semantic anchor regexes. Semantic anchors are tags and never attributes. */
export const ANCHOR_PATTERNS = {
  graphDocument: /^GD-[A-Z0-9]+(?:-[A-Z0-9]+)*$/,
  verificationDocument: /^VD-[A-Z0-9]+(?:-[A-Z0-9]+)*$/,
  change: /^C-[A-Z0-9]+(?:-[A-Z0-9]+)*$/,
  module: /^M-[A-Z0-9]+(?:-[A-Z0-9]+)*$/,
  verification: /^V-M-[A-Z0-9]+(?:-[A-Z0-9]+)*$/,
  dataFlow: /^DF-[A-Z0-9]+(?:-[A-Z0-9]+)*$/,
  task: /^T-[0-9]{3}$/,
} as const;

/** Current-state validation issue emitted by GRACE 4 validators. */
export type Grace4Issue = {
  severity: "error" | "warning";
  code: string;
  file: string;
  line?: number;
  message: string;
};

/** Resolved canonical .grace path set for one project root. */
export type Grace4ProjectPaths = {
  root: string;
  graceDir: string;
  contextDir: string;
  graphIndex: string;
  graphDir: string;
  verificationIndex: string;
  verificationDir: string;
  changesActiveDir: string;
  changesArchiveDir: string;
};

/** Kind of GRACE project detected at a filesystem root. */
export type GraceProjectKind = "grace4" | "grace3" | "none";

/** Resolves canonical GRACE 4 project paths from a repository root. */
export function resolveGrace4Paths(root: string): Grace4ProjectPaths;

/** Detects whether a root contains .grace, legacy docs, or no GRACE artifacts. */
export function detectGraceProjectKind(root: string): GraceProjectKind;

/** Returns a user-facing message for legacy GRACE 3 projects without validating them. */
export function formatGrace3MigrationGuidance(root: string): string;

import { XMLParser } from "fast-xml-parser";
import type { Grace4Issue } from "./types";

/** Parsed XML node preserving the original tag name and child order. */
export type GraceXmlNode = {
  tag: string;
  attributes: Record<string, string>;
  children: GraceXmlNode[];
  text: string;
};

/** Parsed GRACE XML artifact root plus diagnostics. */
export type ParsedGraceXmlArtifact = {
  file: string;
  root: GraceXmlNode | null;
  issues: Grace4Issue[];
};

/** Parser configured for dynamic GRACE tag names and explicit attributes. */
export function createGraceXmlParser(): XMLParser;

/** Parses one XML artifact string into a normalized root node and parse diagnostics. */
export function parseGraceXmlArtifact(file: string, text: string): ParsedGraceXmlArtifact;

/** Reads and parses one XML artifact from disk. Missing files produce a validation issue. */
export function readGraceXmlArtifact(file: string): ParsedGraceXmlArtifact;

/** Returns direct children whose tag exactly matches the requested name. */
export function childNodes(node: GraceXmlNode, tag: string): GraceXmlNode[];

/** Returns the first direct child text value for the requested tag. */
export function childText(node: GraceXmlNode, tag: string): string | undefined;

/** Walks all descendants depth-first, including the starting node. */
export function walkNodes(node: GraceXmlNode): Iterable<GraceXmlNode>;

/** Returns true when the node has any attributes other than the allowed list. */
export function hasForbiddenAttributes(node: GraceXmlNode, allowed: ReadonlySet<string>): boolean;

import type { Grace4Issue, Grace4ProjectPaths } from "./types";
import type { ParsedGraceXmlArtifact, GraceXmlNode } from "./xml";

/** Result of validating a single GRACE 4 artifact. */
export type ArtifactValidationResult = {
  file: string;
  rootTag?: string;
  graceVersion?: string;
  issues: Grace4Issue[];
};

/** Result of validating all current .grace documents in one project. */
export type Grace4ValidationResult = {
  root: string;
  issues: Grace4Issue[];
  artifacts: ArtifactValidationResult[];
};

/** Validates the root tag, graceVersion, and allowed root attributes for one artifact. */
export function validateArtifactRoot(artifact: ParsedGraceXmlArtifact): ArtifactValidationResult;

/** Validates that semantic anchors appear only as tags and never as attributes. */
export function validateSemanticAnchorDiscipline(file: string, root: GraceXmlNode): Grace4Issue[];

/** Validates the five mandatory context artifacts and applicability semantics. */
export function validateContextArtifacts(paths: Grace4ProjectPaths): ArtifactValidationResult[];

/** Validates GraceChangeSpec and GraceChangePlan root statuses and C-* wrapper shape. */
export function validateChangeArtifact(artifact: ParsedGraceXmlArtifact, location: "active" | "archive"): ArtifactValidationResult;

/** Validates current-state .grace artifact grammar and lifecycle location invariants. */
export function validateGrace4Project(root: string): Grace4ValidationResult;

import type { Grace4Issue, Grace4ProjectPaths } from "./types";

/** One graph anchor owned by a graph document. */
export type GraphAnchorRecord = {
  id: string;
  kind: "module" | "data-flow";
  owner: string;
  file: string;
  text: string;
  links: string[];
};

/** Unified current graph projection independent of physical segmentation. */
export type GraphProjection = {
  documents: Map<string, string>;
  modules: Map<string, GraphAnchorRecord>;
  dataFlows: Map<string, GraphAnchorRecord>;
  issues: Grace4Issue[];
};

/** One aggregate V-M-* verification contract owned by a verification document. */
export type VerificationAnchorRecord = {
  id: string;
  moduleId: string;
  owner: string;
  file: string;
  commands: string[];
  scenarios: string[];
  markers: string[];
};

/** Unified current verification projection independent of physical segmentation. */
export type VerificationProjection = {
  documents: Map<string, string>;
  entries: Map<string, VerificationAnchorRecord>;
  issues: Grace4Issue[];
};

/** Builds and validates the logical graph projection from .grace/graph. */
export function buildGraphProjection(paths: Grace4ProjectPaths): GraphProjection;

/** Builds and validates the logical verification projection from .grace/verification. */
export function buildVerificationProjection(paths: Grace4ProjectPaths, graph: GraphProjection): VerificationProjection;

import type { Grace4Issue, Grace4ProjectPaths } from "./types";
import type { GraphProjection, VerificationProjection } from "./projections";

/** Supported machine-checkable GRACE 4 assertion kinds. */
export type AssertionKind =
  | "MustExist"
  | "MustNotExist"
  | "MustOwn"
  | "MustLink"
  | "MustVerify"
  | "MustPassCommand"
  | "MustContain"
  | "MustNotContain";

/** Parsed assertion from BaselineAssertions or TargetAssertions. */
export type GraceAssertion = {
  kind: AssertionKind;
  file: string;
  values: string[];
};

/** Context required to evaluate a GRACE 4 assertion. */
export type AssertionContext = {
  root: string;
  graph: GraphProjection;
  verification: VerificationProjection;
};

/** Evaluates one assertion and returns current-state issues. */
export function evaluateAssertion(assertion: GraceAssertion, context: AssertionContext): Grace4Issue[];

/** Extracts assertions from BaselineAssertions or TargetAssertions under a GraceChangePlan. */
export function extractAssertions(planFile: string, section: "BaselineAssertions" | "TargetAssertions"): GraceAssertion[];

/** Durable semantic scope declared by a GraceChangePlan. */
export type DurableScope = {
  graphAnchors: string[];
  verificationAnchors: string[];
  contextArtifacts: string[];
  graphDocuments: string[];
  verificationDocuments: string[];
};

/** Observed repository write scope declared by a GraceChangePlan. */
export type ObservedWriteScope = {
  files: string[];
  globs: string[];
};

/** Active change summary used for overlap detection and status reporting. */
export type ActiveChangeScope = {
  changeId: string;
  bundlePath: string;
  specStatus: string;
  planStatus?: string;
  durable: DurableScope;
  observedWrites: ObservedWriteScope;
};

/** Reads active change bundles and extracts declared scopes from approved or draft plans. */
export function collectActiveChangeScopes(paths: Grace4ProjectPaths): ActiveChangeScope[];

/** Returns overlap diagnostics without blocking coexistence of approved plans. */
export function detectScopeOverlaps(changes: ActiveChangeScope[]): Grace4Issue[];

/** Returns blocking diagnostics for attempted concurrent or parallel-safe execution. */
export function detectUnsafeConcurrentExecution(changes: ActiveChangeScope[]): Grace4Issue[];

import type { GraphAnchorRecord, GraphProjection, VerificationAnchorRecord, VerificationProjection } from "../grace4/projections";
import type { Grace4Issue } from "../grace4/types";

/** Module record resolved from the GRACE 4 current graph projection. */
export type Grace4ModuleRecord = {
  id: string;
  graph: GraphAnchorRecord;
  verification: VerificationAnchorRecord | null;
  localFiles: FileMarkupRecord[];
};

/** Projection-backed artifact index used by module, verification, and file commands. */
export type GraceArtifactIndex = {
  root: string;
  graph: GraphProjection;
  verification: VerificationProjection;
  modules: Grace4ModuleRecord[];
  verifications: VerificationAnchorRecord[];
  files: FileMarkupRecord[];
  issues: Grace4Issue[];
};

/** Loads the GRACE 4 projection-backed artifact index for a project root. */
export function loadGraceArtifactIndex(root: string): GraceArtifactIndex;

/** Finds modules by module id, text content, path, dependency, or verification id. */
export function findModules(index: GraceArtifactIndex, options: ModuleFindOptions): ModuleMatch[];

/** Resolves one module by M-* id or observed file path. */
export function resolveModule(index: GraceArtifactIndex, value: string): Grace4ModuleRecord | null;

/** Finds verification entries by V-M-* id, module id, command, scenario, or marker text. */
export function findVerifications(index: GraceArtifactIndex, options: VerificationFindOptions): VerificationMatch[];

/** Resolves one verification entry by V-M-* id or module id. */
export function resolveVerification(index: GraceArtifactIndex, value: string): VerificationAnchorRecord | null;

import { detectGraceProjectKind, formatGrace3MigrationGuidance } from "../grace4/project";
import { validateGrace4Project } from "../grace4/grammar";
import type { LintOptions, LintResult } from "./types";

/** Options for GRACE 4 linting. No GRACE 3 compatibility switches are supported. */
export type LintOptions = {
  profile?: LintProfile;
};

/** Lints the current GRACE 4 .grace document state and file-local semantic markup. */
export function lintGraceProject(root: string, options: LintOptions = {}): LintResult {
  const kind = detectGraceProjectKind(root);
  if (kind === "grace3") {
    return lintResultWithSingleError(root, "project.grace3-detected", formatGrace3MigrationGuidance(root), options);
  }
  if (kind === "none") {
    return lintResultWithSingleError(root, "project.missing-grace", "No .grace directory found.", options);
  }

  const validation = validateGrace4Project(root);
  return lintResultFromGrace4Validation(root, validation, options);
}

/** Converts GRACE 4 validation diagnostics into the public grace-lint result shape. */
export function lintResultFromGrace4Validation(root: string, validation: Grace4ValidationResult, options: LintOptions): LintResult;

/** Current state of one GRACE 4 change bundle. */
export type ChangeBundleStatus = {
  changeId: string;
  location: "active" | "archive";
  specStatus?: string;
  planStatus?: string;
  derivedStates: string[];
  path: string;
};

/** GRACE 4 status result for text or JSON output. */
export type StatusResult = {
  schemaVersion: string;
  tool: "grace-status";
  generatedAt: string;
  root: string;
  summary: {
    graceVersion?: string;
    contextArtifacts: number;
    graphModules: number;
    verificationEntries: number;
    activeChanges: number;
    archivedChanges: number;
    integrityErrors: number;
    integrityWarnings: number;
  };
  changes: ChangeBundleStatus[];
  derivedStates: string[];
  integrity: {
    errors: number;
    warnings: number;
    topIssues: string[];
  };
  nextAction: string;
};

/** Collects status without mutating any .grace artifact. */
export function collectProjectStatus(root: string, options?: StatusOptions): StatusResult;

/** Loads projection-backed index or throws a user-facing command error. */
function loadGrace4IndexOrThrow(root: string): GraceArtifactIndex;

/** Handles `grace module find` by querying Graph Projection records. */
async function runModuleFind(root: string, query: string, options: ModuleFindCommandOptions): Promise<void>;

/** Handles `grace module show` by resolving M-* or observed file path to graph plus verification context. */
async function runModuleShow(root: string, value: string, options: ModuleShowCommandOptions): Promise<void>;

/** Handles `grace verification find` by querying Verification Projection records. */
async function runVerificationFind(root: string, query: string, options: VerificationFindCommandOptions): Promise<void>;

/** Handles `grace file show` for file-local/private semantic markup without requiring GRACE 3 shared docs. */
async function runFileShow(root: string, filePath: string, options: FileShowCommandOptions): Promise<void>;

/** Writes a minimal valid GRACE 4 project to a temporary directory. */
export function writeMinimalGrace4Project(root: string): void;

/** Writes a GRACE 4 project with segmented graph and verification documents. */
export function writeSegmentedGrace4Project(root: string): void;

/** Writes one active or archived change bundle fixture. */
export function writeChangeBundleFixture(root: string, options: {
  changeId: string;
  location: "active" | "archive";
  specStatus: string;
  planStatus?: string;
  planBody?: string;
}): void;

/** Writes a legacy GRACE 3 docs fixture used only for migration guidance tests. */
export function writeLegacyGrace3Project(root: string): void;

describe("GRACE 4 projection validation", () => {
  test("monolithic and segmented graph fixtures produce equivalent module ids", () => {
    // Build both fixtures, call buildGraphProjection(), compare sorted module ids.
  });

  test("every M-* requires deterministic V-M-* coverage", () => {
    // Remove one V-M-* fixture entry and assert verification coverage error.
  });
});

describe("GRACE 4 assertions and scope", () => {
  test("stale BaselineAssertions fail after durable state changes", () => {
    // Write a plan expecting an anchor, remove it from projection, assert failure.
  });

  test("overlapping approved plans are warnings but unsafe parallel writes are blockers", () => {
    // Two active approved fixtures share DurableScope and ObservedWriteScope.
  });
});

// Version sync contract:
// package.json: "version": "4.0.0"
// openpackage.yml: version: 4.0.0
// .claude-plugin/marketplace.json metadata.version: "4.0.0"
// .claude-plugin/marketplace.json plugins[0].version: "4.0.0"
// plugins/grace/.claude-plugin/plugin.json version: "4.0.0"
// src/grace.ts meta.version: "4.0.0"
// README.md: Current packaged version: `4.0.0`
// CHANGELOG.md: ## [4.0.0] - 2026-06-20

// README GRACE 4 quick start contract:
// 1. Run $grace-init to create .grace
// 2. Fill .grace/context artifacts
// 3. Run $grace-spec for a change
// 4. Run $grace-plan after spec approval
// 5. Run grace lint --path /path/to/project
// 6. Run grace status --path /path/to/project
// 7. Run $grace-execute and choose sequential or parallel-safe mode
// Existing GRACE 3 projects use $grace-migrate.

/** Required published GRACE 4 skill directory names. */
const REQUIRED_GRACE4_SKILLS = new Set([
  "grace-init",
  "grace-spec",
  "grace-plan",
  "grace-execute",
  "grace-refactor",
  "grace-setup-subagents",
  "grace-fix",
  "grace-refresh",
  "grace-status",
  "grace-ask",
  "grace-cli",
  "grace-explainer",
  "grace-verification",
  "grace-reviewer",
  "grace-migrate",
]);

/** Skill names that must not be published in the GRACE 4 marketplace manifest. */
const FORBIDDEN_GRACE4_SKILLS = new Set(["grace-multiagent-execute"]);

/** Validates that the marketplace skills array matches the GRACE 4 release surface. */
function validateGrace4SkillSurface(entry: JsonObject, errors: string[]): void;

/** Validates that package.json declares fast-xml-parser as a runtime dependency. */
function validateGrace4Dependencies(errors: string[]): void;

/** Final verification commands for the GRACE 4 release implementation. */
export const GRACE4_RELEASE_VERIFICATION = [
  "bun test",
  "bun run ./src/grace.ts lint --path /tmp/grace4-valid-fixture",
  "bun run ./src/grace.ts status --path /tmp/grace4-valid-fixture --json --fail-on never",
  "bun run ./scripts/validate-marketplace.ts",
  "bun run validate:release",
] as const;

/** This implementation must not migrate repository-local GRACE 3 docs. */
export const REPO_SELF_MIGRATION_FORBIDDEN = true;
